import fs from 'fs';
import os from 'os';
import path from 'path';
import { getConfigAccountIfExists as __getConfigAccountIfExists } from '@hubspot/local-dev-lib/config';
import { HUBSPOT_ACCOUNT_TYPES } from '@hubspot/local-dev-lib/constants/config';
import { afterAll, afterEach, beforeAll, beforeEach, describe, expect, it, vi, } from 'vitest';
import { OUTPUT_DIR } from '../constants.js';
import { UnifiedAppAuthTypes } from '../types.js';
import { buildSourceId, generateCrmSearchReferenceId, generateHash, getUrlSafeFileName, isExtensionFile, isNodeModule, isTestOrSandboxAccount, isUnifiedAppConfig, loadManifest, stripAnsiColorCodes, warnAboutIgnoredConfigFiles, } from '../utils.js';
import { createMockLogger } from './factories.js';
vi.mock('@hubspot/local-dev-lib/config');
const getConfigAccountIfExists = __getConfigAccountIfExists;
describe('utils', () => {
    describe('getUrlSafeFileName', () => {
        it('should uri encode the filename', () => {
            const fileName = 'test File ?@#$%^&*()Name who would name a file like this!';
            const actual = getUrlSafeFileName(`${fileName}.tsx`);
            expect(actual).toEqual(`${encodeURIComponent(fileName)}.js`);
        });
    });
    describe('stripAnsiColorCodes', () => {
        it('should strip all color codes out of a string', () => {
            const withColorCodes = '\x1B[33mThis is a test\x1B[39m';
            const actual = stripAnsiColorCodes(withColorCodes);
            expect(actual).toEqual('This is a test');
        });
        it('should return null if the provided string is null', () => {
            const actual = stripAnsiColorCodes(undefined);
            expect(actual).toEqual(null);
        });
        it('should return null if the provided string is undefined', () => {
            const actual = stripAnsiColorCodes(undefined);
            expect(actual).toEqual(null);
        });
        it('should return null if the provided string is empty', () => {
            const actual = stripAnsiColorCodes('');
            expect(actual).toEqual(null);
        });
    });
    describe('loadManifest', () => {
        beforeEach(() => {
            vi.spyOn(fs, 'readFileSync').mockReturnValue(JSON.stringify({
                manifest: true,
            }));
        });
        afterEach(() => {
            vi.restoreAllMocks();
        });
        it('should return the manifest file when it is able to load it from disk', () => {
            const actual = loadManifest(OUTPUT_DIR, 'test-file-name');
            expect(fs.readFileSync).toHaveBeenCalledTimes(1);
            expect(actual).toStrictEqual({
                manifest: true,
            });
        });
        it('should return an empty object when it fails to load from disk', () => {
            vi.spyOn(fs, 'readFileSync').mockImplementationOnce(() => {
                throw new Error('OH NO!');
            });
            const actual = loadManifest(OUTPUT_DIR, 'test-file-name');
            expect(actual).toStrictEqual({});
        });
    });
    describe('buildSourceId', () => {
        it('should return null when there is no uid in app config', () => {
            expect(buildSourceId({}, { data: { uid: 'some-uid' } })).toBe(null);
        });
        it('should return null when there is no uid in extension config', () => {
            expect(buildSourceId({ uid: 'some-uid' }, { data: {} })).toBe(null);
        });
        it('should return a valid sourceId', () => {
            const appUID = 'app-uid';
            const extensionUID = 'extension-uid';
            expect(buildSourceId({ uid: appUID }, { data: { uid: extensionUID } })).toBe(`${appUID}::${extensionUID}`);
        });
    });
    describe('isNodeModule', () => {
        it('should return false if the path is undefined', () => {
            expect(isNodeModule(undefined)).toBe(false);
        });
        it('should return false if the path is not a node_modules', () => {
            expect(isNodeModule('foo.js')).toBe(false);
        });
        it('should return true if the path is a node_modules', () => {
            expect(isNodeModule('node_modules/foo.js')).toBe(true);
        });
    });
    describe('isExtensionFile', () => {
        /**
         * This function relies on the file system. Mocking doesn't allow us to fully test all scenarios.
         * In order to effectively test it, we need to create a temporary directory structure.
         * Being thorough here allows us to safely mock it elsewhere.
         */
        const tempDir = path.join(__dirname, 'temp');
        const extensionDir = path.join(tempDir, 'test/path/extension');
        const indexFile = path.join(extensionDir, 'index.js');
        const nestedFile = path.join(extensionDir, 'src/file.ts');
        const otherFile = path.join(tempDir, 'different/path/file.ts');
        const relativeOtherFile = path.join(tempDir, '../different/path/file.ts');
        beforeAll(() => {
            fs.mkdirSync(extensionDir, { recursive: true });
            fs.mkdirSync(path.dirname(nestedFile), { recursive: true });
            fs.mkdirSync(path.dirname(otherFile), { recursive: true });
            fs.mkdirSync(path.dirname(relativeOtherFile), { recursive: true });
            fs.writeFileSync(otherFile, '');
            fs.writeFileSync(nestedFile, '');
            fs.writeFileSync(indexFile, '');
            fs.writeFileSync(relativeOtherFile, '');
        });
        afterAll(() => {
            fs.rmSync(tempDir, { recursive: true, force: true });
            fs.rmSync(relativeOtherFile, { recursive: true, force: true });
        });
        it('should return false if filepath is undefined', () => {
            expect(isExtensionFile(undefined, extensionDir)).toBe(false);
        });
        it('should return true if file is within extension path', () => {
            expect(isExtensionFile(nestedFile, extensionDir)).toBe(true);
            expect(isExtensionFile(indexFile, extensionDir)).toBe(true);
        });
        it('should return false if file is outside extension path', () => {
            expect(isExtensionFile(otherFile, extensionDir)).toBe(false);
        });
        it('should handle relative paths correctly', () => {
            const originalCwd = process.cwd();
            process.chdir(tempDir);
            expect(isExtensionFile('./test/path/extension/src/file.ts', './test/path/extension')).toBe(true);
            expect(isExtensionFile('../different/path/file.ts', './test/path/extension')).toBe(false);
            process.chdir(originalCwd);
        });
        it('should return true if the extension path is nested within the provided path', () => {
            const originalCwd = process.cwd();
            process.chdir(tempDir);
            expect(isExtensionFile('../temp/test/path/extension/src/file.ts', './test/path/extension/')).toBe(true);
            process.chdir(originalCwd);
        });
    });
    describe('isUnifiedAppConfig', () => {
        it('should return true for a unified app config', () => {
            const config = {
                unified: true,
                name: 'Test',
                uid: 'test-uid',
                auth: { type: UnifiedAppAuthTypes.OAUTH },
                distribution: 'private',
                isPublicApp: true,
                extensions: { crm: { cards: [] } },
            };
            expect(isUnifiedAppConfig(config)).toBe(true);
        });
        it('should return false for a legacy app config', () => {
            const config = {
                name: 'Test',
                uid: 'test-uid',
                scopes: [],
                public: false,
                extensions: { crm: { cards: [] } },
            };
            expect(isUnifiedAppConfig(config)).toBe(false);
        });
    });
    describe('generateHash', () => {
        it('should generate consistent hashes for same inputs', () => {
            const hash1 = generateHash('test', ['a', 'b'], { foo: 'bar' });
            const hash2 = generateHash('test', ['a', 'b'], { foo: 'bar' });
            expect(hash1).toBe(hash2);
        });
        it('should handle different types of arguments', () => {
            expect(generateHash('test')).toBe('364492');
            expect(generateHash(123)).toBe('be32');
            expect(generateHash(['a', 'b'])).toBe('171f6');
            expect(generateHash({ foo: 'bar' })).toBe('4a4201ac');
            expect(generateHash(null)).toBe('33c587');
            expect(generateHash(undefined)).toBe('42201c7f');
        });
        it('should generate the correct hash for multiple arguments', () => {
            const hash1 = generateHash('arg1', ['foo', 'bar']);
            const hash2 = generateHash('test', ['a', 'c', 'd', 'e']);
            expect(hash1).toBe('1ec304f1');
            expect(hash2).toBe('607ad458');
        });
        it('should normalize arrays regardless of order', () => {
            const hash1 = generateHash(['a', 'b', 'c']);
            const hash2 = generateHash(['c', 'a', 'b']);
            expect(hash1).toBe(hash2);
        });
        it('should normalize objects regardless of key order', () => {
            const hash1 = generateHash({ a: 1, b: 2 });
            const hash2 = generateHash({ b: 2, a: 1 });
            expect(hash1).toBe(hash2);
        });
        it('should return an empty string and log an error if an error is thrown', () => {
            // Mock console.error to prevent it from logging to the console
            const consoleErrorSpy = vi
                .spyOn(console, 'error')
                .mockImplementation(() => { });
            // Create an argument that will cause an error.
            const circularReference = {};
            circularReference.self = circularReference;
            const hash = generateHash(circularReference);
            expect(hash).toBe('');
            expect(consoleErrorSpy).toHaveBeenCalledWith('Error generating hash: ', expect.any(TypeError));
            // Restore console.error
            consoleErrorSpy.mockRestore();
        });
    });
    describe('generateCrmSearchReferenceId', () => {
        it('should generate consistent hashes for same inputs', () => {
            const hash1 = generateCrmSearchReferenceId({
                objectType: 'contact',
                properties: ['firstname', 'email'],
            });
            const hash2 = generateCrmSearchReferenceId({
                objectType: 'contact',
                properties: ['firstname', 'email'],
            });
            expect(hash1).toBe(hash2);
        });
        it('should sort properties before hashing', () => {
            const hash1 = generateCrmSearchReferenceId({
                objectType: 'contact',
                properties: ['email', 'firstname', 'lastname'],
            });
            const hash2 = generateCrmSearchReferenceId({
                objectType: 'contact',
                properties: ['lastname', 'email', 'firstname'],
            });
            expect(hash1).toBe(hash2);
        });
        it('should produce different hashes for different objectTypes', () => {
            const hash1 = generateCrmSearchReferenceId({
                objectType: 'contact',
                properties: ['firstname'],
            });
            const hash2 = generateCrmSearchReferenceId({
                objectType: 'deal',
                properties: ['firstname'],
            });
            expect(hash1).not.toBe(hash2);
        });
        it('should produce different hashes for different queries', () => {
            const hash1 = generateCrmSearchReferenceId({
                objectType: 'contact',
                properties: ['firstname'],
                query: 'John',
            });
            const hash2 = generateCrmSearchReferenceId({
                objectType: 'contact',
                properties: ['firstname'],
                query: 'Jane',
            });
            expect(hash1).not.toBe(hash2);
        });
        it('should produce different hashes for different filterGroups', () => {
            const hash1 = generateCrmSearchReferenceId({
                objectType: 'deal',
                properties: ['dealname'],
                filterGroups: [
                    {
                        filters: [
                            { propertyName: 'amount', operator: 'GT', value: '10000' },
                        ],
                    },
                ],
            });
            const hash2 = generateCrmSearchReferenceId({
                objectType: 'deal',
                properties: ['dealname'],
                filterGroups: [
                    {
                        filters: [
                            { propertyName: 'amount', operator: 'GT', value: '50000' },
                        ],
                    },
                ],
            });
            expect(hash1).not.toBe(hash2);
        });
        it('should produce different hashes for different sorts', () => {
            const hash1 = generateCrmSearchReferenceId({
                objectType: 'deal',
                properties: ['dealname'],
                sorts: [{ propertyName: 'amount', direction: 'ASCENDING' }],
            });
            const hash2 = generateCrmSearchReferenceId({
                objectType: 'deal',
                properties: ['dealname'],
                sorts: [{ propertyName: 'amount', direction: 'DESCENDING' }],
            });
            expect(hash1).not.toBe(hash2);
        });
        it('should produce different hashes for different limits', () => {
            const hash1 = generateCrmSearchReferenceId({
                objectType: 'contact',
                properties: ['firstname'],
                limit: 10,
            });
            const hash2 = generateCrmSearchReferenceId({
                objectType: 'contact',
                properties: ['firstname'],
                limit: 25,
            });
            expect(hash1).not.toBe(hash2);
        });
        it('should handle omitted optional fields as defaults', () => {
            const hashMinimal = generateCrmSearchReferenceId({
                objectType: 'contact',
            });
            const hashExplicitDefaults = generateCrmSearchReferenceId({
                objectType: 'contact',
                query: undefined,
                filterGroups: undefined,
                properties: undefined,
                sorts: undefined,
                limit: undefined,
            });
            expect(hashMinimal).toBe(hashExplicitDefaults);
        });
        it('should match the runtime hash format (CrmSearch:: prefix with :: separators)', () => {
            // Verifies the exact hash output matches what ui-extensibility's
            // generateSearchReferenceId produces for the same inputs.
            expect(generateCrmSearchReferenceId({
                objectType: 'contact',
                properties: ['email', 'firstname', 'lastname'],
            })).toBe('299ba0a8');
            expect(generateCrmSearchReferenceId({
                objectType: 'contact',
                properties: ['firstname'],
                query: 'John',
            })).toBe('1c0a7ad9');
            expect(generateCrmSearchReferenceId({
                objectType: 'contact',
                properties: ['firstname'],
                limit: 25,
            })).toBe('2ba03923');
        });
    });
    describe('isTestOrSandboxAccount', () => {
        const accountId = 123;
        afterEach(() => {
            vi.resetAllMocks();
        });
        it('returns false when the account is not in config', async () => {
            getConfigAccountIfExists.mockReturnValue(undefined);
            expect(await isTestOrSandboxAccount(accountId)).toBe(false);
        });
        it('returns false for a STANDARD account with no parent', async () => {
            getConfigAccountIfExists.mockReturnValue({
                accountType: HUBSPOT_ACCOUNT_TYPES.STANDARD,
            });
            expect(await isTestOrSandboxAccount(accountId)).toBe(false);
        });
        it('returns true for a DEVELOPER_TEST account', async () => {
            getConfigAccountIfExists.mockReturnValue({
                accountType: HUBSPOT_ACCOUNT_TYPES.DEVELOPER_TEST,
            });
            expect(await isTestOrSandboxAccount(accountId)).toBe(true);
        });
        it('returns true for a DEVELOPMENT_SANDBOX account', async () => {
            getConfigAccountIfExists.mockReturnValue({
                accountType: HUBSPOT_ACCOUNT_TYPES.DEVELOPMENT_SANDBOX,
            });
            expect(await isTestOrSandboxAccount(accountId)).toBe(true);
        });
        it('returns true for a STANDARD_SANDBOX account', async () => {
            getConfigAccountIfExists.mockReturnValue({
                accountType: HUBSPOT_ACCOUNT_TYPES.STANDARD_SANDBOX,
            });
            expect(await isTestOrSandboxAccount(accountId)).toBe(true);
        });
        it('returns true for any account with a parentAccountId', async () => {
            getConfigAccountIfExists.mockReturnValue({
                accountType: HUBSPOT_ACCOUNT_TYPES.APP_DEVELOPER,
                parentAccountId: 999,
            });
            expect(await isTestOrSandboxAccount(accountId)).toBe(true);
        });
        it('returns false for APP_DEVELOPER with no parentAccountId', async () => {
            getConfigAccountIfExists.mockReturnValue({
                accountType: HUBSPOT_ACCOUNT_TYPES.APP_DEVELOPER,
            });
            expect(await isTestOrSandboxAccount(accountId)).toBe(false);
        });
        it('returns false for STANDARD even when parentAccountId is somehow set', async () => {
            getConfigAccountIfExists.mockReturnValue({
                accountType: HUBSPOT_ACCOUNT_TYPES.STANDARD,
                parentAccountId: 999,
            });
            expect(await isTestOrSandboxAccount(accountId)).toBe(false);
        });
        it('returns false when getConfigAccountIfExists throws (no config file)', async () => {
            getConfigAccountIfExists.mockImplementation(() => {
                throw new Error('No config file found');
            });
            expect(await isTestOrSandboxAccount(accountId)).toBe(false);
        });
    });
});
describe('warnAboutIgnoredConfigFiles', () => {
    let tmpDir;
    beforeEach(() => {
        tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), 'uie-warn-spec-'));
    });
    afterEach(() => {
        fs.rmSync(tmpDir, { recursive: true, force: true });
    });
    it('warns with the correct label when a vite config file is present', () => {
        const logger = createMockLogger();
        fs.writeFileSync(path.join(tmpDir, 'vite.config.ts'), '');
        warnAboutIgnoredConfigFiles(tmpDir, logger);
        expect(logger.warn).toHaveBeenCalledWith(expect.stringContaining('Vite config found in extension source (vite.config.ts) and ignored'));
    });
    it('warns with the correct label when a postcss config file is present', () => {
        const logger = createMockLogger();
        fs.writeFileSync(path.join(tmpDir, 'postcss.config.js'), '');
        warnAboutIgnoredConfigFiles(tmpDir, logger);
        expect(logger.warn).toHaveBeenCalledWith(expect.stringContaining('PostCSS config found in extension source (postcss.config.js) and ignored'));
    });
    it('warns with the correct label when a .env file is present', () => {
        const logger = createMockLogger();
        fs.writeFileSync(path.join(tmpDir, '.env'), '');
        warnAboutIgnoredConfigFiles(tmpDir, logger);
        expect(logger.warn).toHaveBeenCalledWith(expect.stringContaining('Environment file found in extension source (.env) and ignored'));
    });
    it('stays silent on a clean directory', () => {
        const logger = createMockLogger();
        warnAboutIgnoredConfigFiles(tmpDir, logger);
        expect(logger.warn).not.toHaveBeenCalled();
    });
    it('does not throw when the directory does not exist', () => {
        const logger = createMockLogger();
        expect(() => warnAboutIgnoredConfigFiles('/does/not/exist/ever', logger)).not.toThrow();
        expect(logger.warn).not.toHaveBeenCalled();
    });
});
